enhanced_schema:
{
  "tables": [
    {
      "table_name": "player",
      "table_description": "Stores information about players.",
      "columns": [
        {
          "name": "player_id",
          "type": "INTEGER",
          "description": "Unique identifier for each player"
        },
        {
          "name": "first_name",
          "type": "VARCHAR",
          "description": "Player's first name"
        },
        {
          "name": "last_name",
          "type": "VARCHAR",
          "description": "Player's last name"
        },
        {
          "name": "team_id",
          "type": "INTEGER",
          "description": "Identifier for the team the player is part of"
        },
        {
          "name": "position",
          "type": "VARCHAR",
          "description": "Player's position"
        }
      ],
      "primary_key": [
        "player_id"
      ],
      "foreign_keys": [
        {
          "column": "team_id",
          "references": "team"
        }
      ]
    },
    {
      "table_name": "team",
      "table_description": "Stores information about teams.",
      "columns": [
        {
          "name": "team_id",
          "type": "INTEGER",
          "description": "Unique identifier for each team"
        },
        {
          "name": "team_name",
          "type": "VARCHAR",
          "description": "Name of the team"
        },
        {
          "name": "division",
          "type": "VARCHAR",
          "description": "Division of the team"
        }
      ],
      "primary_key": [
        "team_id"
      ]
    },
    {
      "table_name": "game",
      "table_description": "Stores information about games.",
      "columns": [
        {
          "name": "game_id",
          "type": "INTEGER",
          "description": "Unique identifier for each game"
        },
        {
          "name": "game_date",
          "type": "DATE",
          "description": "Date of the game"
        },
        {
          "name": "home_team_id",
          "type": "INTEGER",
          "description": "Identifier for the home team"
        },
        {
          "name": "away_team_id",
          "type": "INTEGER",
          "description": "Identifier for the away team"
        },
        {
          "name": "location",
          "type": "VARCHAR",
          "description": "Location of the game"
        }
      ],
      "primary_key": [
        "game_id"
      ],
      "foreign_keys": [
        {
          "column": "home_team_id",
          "references": "team"
        },
        {
          "column": "away_team_id",
          "references": "team"
        }
      ]
    },
    {
      "table_name": "user",
      "table_description": "Stores user information and roles.",
      "columns": [
        {
          "name": "user_id",
          "type": "INTEGER",
          "description": "Unique identifier for each user"
        },
        {
          "name": "username",
          "type": "VARCHAR",
          "description": "Username for the user"
        },
        {
          "name": "password_hash",
          "type": "VARCHAR",
          "description": "Hashed password for security"
        },
        {
          "name": "role",
          "type": "VARCHAR",
          "description": "User role (e.g., coach, analyst, manager)"
        }
      ],
      "primary_key": [
        "user_id"
      ]
    },
    {
      "table_name": "player_performance",
      "table_description": "Records detailed performance statistics of players in baseball games against various teams.",
      "columns": [
        {
          "name": "performance_id",
          "type": "INTEGER",
          "description": "Unique identifier for each performance record"
        },
        {
          "name": "player_id",
          "type": "INTEGER",
          "description": "Identifier for the player"
        },
        {
          "name": "game_id",
          "type": "INTEGER",
          "description": "Identifier for the game"
        },
        {
          "name": "games_played",
          "type": "INTEGER",
          "description": "Number of games played against the team"
        },
        {
          "name": "at_bats",
          "type": "INTEGER",
          "description": "Number of at-bats in the games"
        },
        {
          "name": "runs",
          "type": "INTEGER",
          "description": "Number of runs scored"
        },
        {
          "name": "hits",
          "type": "INTEGER",
          "description": "Number of hits"
        },
        {
          "name": "doubles",
          "type": "INTEGER",
          "description": "Number of doubles hit"
        },
        {
          "name": "triples",
          "type": "INTEGER",
          "description": "Number of triples hit"
        },
        {
          "name": "home_runs",
          "type": "INTEGER",
          "description": "Number of home runs"
        },
        {
          "name": "runs_batted_in",
          "type": "INTEGER",
          "description": "Number of runs batted in"
        },
        {
          "name": "walks",
          "type": "INTEGER",
          "description": "Number of walks (bases on balls)"
        },
        {
          "name": "strikeouts",
          "type": "INTEGER",
          "description": "Number of strikeouts"
        },
        {
          "name": "stolen_bases",
          "type": "INTEGER",
          "description": "Number of bases stolen"
        },
        {
          "name": "caught_stealing",
          "type": "INTEGER",
          "description": "Number of times caught stealing"
        },
        {
          "name": "total_bases",
          "type": "INTEGER",
          "description": "Total number of bases earned"
        },
        {
          "name": "sacrifice_flies",
          "type": "INTEGER",
          "description": "Number of sacrifice flies"
        },
        {
          "name": "sacrifice_hits",
          "type": "INTEGER",
          "description": "Number of sacrifice hits"
        },
        {
          "name": "hit_by_pitch",
          "type": "INTEGER",
          "description": "Number of times hit by pitch"
        },
        {
          "name": "intentional_walks",
          "type": "INTEGER",
          "description": "Number of intentional walks received"
        },
        {
          "name": "grounded_into_double_plays",
          "type": "INTEGER",
          "description": "Number of times grounded into double plays"
        },
        {
          "name": "batting_average",
          "type": "FLOAT",
          "description": "Batting average"
        },
        {
          "name": "on_base_percentage",
          "type": "FLOAT",
          "description": "On-base percentage"
        },
        {
          "name": "slugging_percentage",
          "type": "FLOAT",
          "description": "Slugging percentage"
        }
      ],
      "primary_key": [
        "performance_id"
      ],
      "foreign_keys": [
        {
          "column": "player_id",
          "references": "player"
        },
        {
          "column": "game_id",
          "references": "game"
        }
      ]
    }
  ]
}
